original_prompt:
{
  "name": "Cyber Security Character",
  "steps": [
    {
      "step_1": "Facial Identity Mapping",
      "description": "Maintain 100% facial consistency based on the provided reference photos. Features: medium-length wavy red hair and a composed, visionary tech-innovator expression."
    },
    {
      "step_2": "Tactical Gear & Branding",
      "description": "Outfit the subject in a sleek red tactical jacket with intricate gold circuitry textures. Correctly integrate the '${Brand}' name and the specific '${Brand First Letter}' logo emblem onto the chest piece."
    },
    {
      "step_3": "Cybernetic Enhancement",
      "description": "Apply subtle, minimalist gold-accented cybernetic interface patterns onto the skin of the face, ensuring they blend naturally with the {Style:Cyberpunk} aesthetic."
    },
    {
      "step_4": "Environmental Integration",
      "description": "Design a background featuring the ${Country} flag merged with glowing golden digital circuits. Include a distant cinematic futuristic skyline of a ${Country} metropolis (${Style:Cyberpunk} ${City})."
    },
    {
      "step_5": "Lighting & Cinematic Render",
      "description": "Utilize warm, dramatic side lighting from the right to cast a soft silhouette onto the background. Render in 4K ultra-realistic quality with hyper-detailed textures."
    }
  ]
}

vi_prompt:
{
  "name": "Nhân vật An ninh mạng",
  "steps": [
    {
      "step_1": "Khớp nối nhận diện khuôn mặt",
      "description": "Duy trì 100% độ nhất quán của khuôn mặt dựa trên ảnh tham chiếu được cung cấp. Đặc điểm: mái tóc đỏ lượn sóng dài ngang vai và nét mặt điềm đạm, thần thái của một nhà đổi mới công nghệ có tầm nhìn xa."
    },
    {
      "step_2": "Trang bị tác chiến & Nhận diện thương hiệu",
      "description": "Trang phục cho nhân vật là chiếc áo khoác chiến thuật màu đỏ bóng bẩy với họa tiết bo mạch vàng tinh xảo. Tích hợp chuẩn xác tên thương hiệu '${Brand}' và biểu trưng logo '${Brand First Letter}' đặc trưng lên phần giáp trước ngực."
    },
    {
      "step_3": "Nâng cấp công nghệ sinh học (Cybernetic)",
      "description": "Áp dụng các hoa văn giao diện điều khiển điều khiển học điểm vàng tối giản, tinh tế lên vùng da mặt, đảm bảo hòa hợp tự nhiên với phong cách thẩm mỹ {Style:Cyberpunk}."
    },
    {
      "step_4": "Tích hợp môi trường bối cảnh",
      "description": "Thiết kế hậu cảnh có hình quốc kỳ ${Country} hòa quyện với các mạch điện tử kỹ thuật số ánh vàng phát sáng. Bổ sung đường chân trời đô thị tương lai chuẩn điện ảnh ở phía xa của một đại đô thị ${Country} (${Style:Cyberpunk} ${City})."
    },
    {
      "step_5": "Ánh sáng & Kết xuất điện ảnh",
      "description": "Sử dụng ánh sáng tạt một bên (side lighting) ấm áp, giàu kịch tính từ bên phải để tạo bóng đổ mềm mại lên phông nền. Kết xuất (render) ở chất lượng siêu thực 4K với các chi tiết bề mặt siêu tinh xảo."
    }
  ]
}
